css:
@media print {
    @page {
        size: 80mm auto;
        margin: 3mm 2.5mm;
    }
    .print-format {
        width: 74mm;
        margin: 0 auto;
        padding: 0;
    }
}

.sar-ticket {
    width: 100%;
    max-width: 74mm;
    margin: 0 auto;
    font-family: "Courier New", Consolas, "Liberation Mono", monospace;
    font-size: 11px;
    line-height: 1.28;
    color: #000 !important;
    background: #fff !important;
}

.sar-ticket * {
    font-family: "Courier New", Consolas, "Liberation Mono", monospace;
    color: #000 !important;
    box-sizing: border-box;
}

.sar-header-block {
    margin-bottom: 4px;
    word-break: break-word;
}

.sar-company-name {
    font-size: 12px;
    font-weight: 700;
    text-transform: uppercase;
}

.sar-commercial-name {
    font-size: 11.5px;
    font-weight: 700;
    text-transform: uppercase;
}

.sar-line {
    margin: 0;
    padding: 0;
    font-size: 10.5px;
    line-height: 1.25;
}

.sar-double-sep {
    border-top: 1px dashed #000;
    border-bottom: 1px dashed #000;
    height: 3px;
    margin: 5px 0;
}

.sar-dash-sep {
    border-top: 1px dashed #000;
    margin: 5px 0;
}

.sar-flex-row {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    gap: 6px;
}

.sar-bold {
    font-weight: 700;
}

.sar-meta-table,
.sar-items-table,
.sar-totals-table,
.sar-footer-table {
    width: 100%;
    border-collapse: collapse;
    margin: 0;
    padding: 0;
}

.sar-meta-table td,
.sar-totals-table td,
.sar-footer-table td {
    padding: 1px 0 !important;
    vertical-align: top;
    font-size: 10.5px;
    line-height: 1.25;
    border: none !important;
}

.sar-exon-block {
    margin: 6px 0 4px 0;
}

.sar-exon-label {
    display: inline-block;
    min-width: 115px;
}

.sar-order-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin: 4px 0 2px 0;
    font-size: 11px;
    font-weight: 700;
}

.sar-items-table th {
    padding: 2px 1px !important;
    font-size: 10px;
    font-weight: 700;
    border-top: none !important;
    border-bottom: none !important;
    vertical-align: bottom;
    text-align: left;
}

.sar-items-table td {
    padding: 1.5px 1px !important;
    font-size: 10.5px;
    line-height: 1.22;
    border: none !important;
    vertical-align: top;
}

.sar-item-subline {
    padding-left: 16px !important;
    font-size: 10px !important;
    line-height: 1.18 !important;
}

.sar-mode-badge {
    padding: 3px 0 2px 16px;
    font-weight: 700;
    font-size: 11px;
    text-transform: uppercase;
}

.sar-totals-label {
    text-align: right;
    padding-right: 10px !important;
    white-space: nowrap;
}

.sar-totals-val {
    text-align: right;
    width: 72px;
    white-space: nowrap;
}

.sar-pay-col {
    text-align: left;
    font-size: 10px !important;
    padding-right: 4px !important;
    word-break: break-word;
}

.sar-words {
    margin: 6px 0;
    font-size: 10.5px;
    font-weight: 700;
    line-height: 1.25;
    text-transform: uppercase;
}

.sar-range-block {
    margin: 5px 0 6px 0;
}

.sar-range-label {
    width: 148px;
    white-space: nowrap;
}

.sar-copy-block {
    margin-top: 6px;
    font-size: 10.5px;
    line-height: 1.25;
}

.text-right {
    text-align: right !important;
}

.text-center {
    text-align: center !important;
}

.restaurant-non-fiscal {
    margin-top: 6px;
}
